/**
 * Darsi content model. Units are plain JSON in public/content/ so they can be cached offline per unit,
 * generated by a CMS later, and read by the kit generator (scripts/build-kits.mjs) to produce slides.
 * Every learner-facing string is a LocalText keyed by BCP-47 language; English is the fallback.
 */
export type Lang = "en" | "ar";
export type LocalText = { en: string } & Partial<Record<string, string>>;
export type LocalList = { en: string[] } & Partial<Record<string, string[]>>;
export type Track = "ai" | "iot" | "cyber";

interface Base { id: string; prompt: LocalText; explain?: LocalText }
export interface ChoiceStep extends Base { type: "choice"; options: { id: string; text: LocalText }[]; answer: string }
export interface MultiStep extends Base { type: "multi"; options: { id: string; text: LocalText }[]; answers: string[] }
export interface TrueFalseStep extends Base { type: "truefalse"; answer: boolean }
export type Art = "sensor" | "lamp" | "phone" | "plant" | "chat" | "calculator";
export interface ImageStep extends Base { type: "image"; options: { id: string; label: LocalText; art: Art }[]; answer: string }
export interface MatchStep extends Base { type: "match"; pairs: { left: LocalText; right: LocalText }[] }
export interface OrderStep extends Base { type: "order"; steps: LocalText[] }
export interface FillStep extends Base { type: "fill"; sentence: { en: Array<string | { blank: number }> } & Partial<Record<string, Array<string | { blank: number }>>>; bank: LocalList; answers: LocalList }
export interface TypeStep extends Base { type: "type"; accept: LocalList; placeholder?: LocalText }
export interface HotspotStep extends Base { type: "hotspot"; mock: { from: string; body: LocalText; link: LocalText }; spots: { id: string; x: number; y: number; w: number; h: number; label: LocalText }[] }
export interface ScenarioStep extends Base { type: "scenario"; who: LocalText; initial: LocalText; situation: LocalText; choices: { id: string; label: LocalText; tone: "good" | "consider"; consequence: LocalText }[] }
export interface ReflectStep extends Base { type: "reflect"; placeholder?: LocalText }
export interface VideoStep extends Base {
  type: "video";
  title: LocalText;
  /** "{lang}" is replaced by the teacher's language. Null until produced — the player then shows the poster and the transcript. */
  src: string | null;
  captions?: Partial<Record<string, string>>;
  duration: number;
  sizeMB: number;
  transcript: LocalText;
  chapters?: { at: number; label: LocalText }[];
  checkpoint?: { at: number; question: ChoiceStep | TrueFalseStep };
}
/** A Labs app id (apps/web/src/labs/apps/<id>), e.g. "prompt", "neuron", "playground". */
export type LabTool = string;
export interface LabStep extends Base { type: "lab"; tool: LabTool }
/** A short reading: the concepts behind the lesson, with key terms. Paragraphs separated by blank lines. */
export interface ReadStep extends Base { type: "read"; title: LocalText; body: LocalText; keyTerms?: { term: LocalText; def: LocalText }[] }
/** A real-world task done in school, submitted as evidence and reviewed by a teacher or admin against a rubric. */
export interface ProjectStep extends Base { type: "project"; task: LocalText; deliverable: LocalText; rubric: { criterion: LocalText }[] }

export type Step = ChoiceStep | MultiStep | TrueFalseStep | ImageStep | MatchStep | OrderStep | FillStep | TypeStep | HotspotStep | ScenarioStep | ReflectStep | VideoStep | LabStep | ReadStep | ProjectStep;
export type GradedStep = ChoiceStep | MultiStep | TrueFalseStep | ImageStep | MatchStep | OrderStep | FillStep | TypeStep | HotspotStep;
export const GRADED = new Set<Step["type"]>(["choice", "multi", "truefalse", "image", "match", "order", "fill", "type", "hotspot"]);

export interface Slide { layout: "title" | "bullets" | "activity" | "questions" | "exit"; title: LocalText; bullets?: LocalList; note?: LocalText; /** Voice-over for the narrated video and the speaker notes in the PPTX (Google Vids uses these). */ narration?: LocalText }
export type KitKind = "slides" | "lesson-plan" | "worksheet" | "video";
export interface KitFile {
  kind: KitKind; title: LocalText; pages: number;
  /** Path under /kits without "-<lang>.<ext>" … */ base?: string;
  /** … or a full path with "{lang}" and no extension (used for /media videos). */ path?: string;
  formats: ("pdf" | "pptx" | "mp4")[];
}
export const kitUrl = (f: KitFile, lang: string, fmt: string) => (f.path ? `${f.path.replace("{lang}", lang)}.${fmt}` : `/kits/${f.base}-${lang}.${fmt}`);

export interface Lesson {
  id: string;
  title: LocalText;
  minutes: number;
  steps: Step[];
  tryTomorrow: LocalText;
  slides: Slide[];
  kit: KitFile[];
  /** Competency codes this lesson builds (see competencies.ts) — feeds the capability view for admins. */
  competencies?: string[];
}
export interface Unit { id: string; track: Track; level: number; title: LocalText; summary: LocalText; lessons: Lesson[] }
export interface CatalogEntry { id: string; track: Track; level: number; title: LocalText; summary: LocalText; lessons: number; sizeMB: number; available: boolean }
export interface Catalog { version: number; units: CatalogEntry[] }
export interface Placement { questions: Array<(ChoiceStep | TrueFalseStep) & { track: Track }> }

/** Pick the string for a language, falling back to English. */
export const pick = (t: LocalText | undefined, lang: string): string => (t ? t[lang] ?? t.en : "");
export const pickList = (t: LocalList | undefined, lang: string): string[] => (t ? t[lang] ?? t.en : []);
